import{z as n,x as o,o as e,c as s,q as B,j as l,D as a,d as t,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"量化省下什么","description":"","frontmatter":{"title":"量化省下什么","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ce-quantization-savings.md","filePath":"llm/ce-quantization-savings.md","lastUpdated":1791413859000}'),d={name:"llm/ce-quantization-savings.md"};function p(F,E,C,D,c,m){const A=o("Mermaid");return e(),s("div",null,[E[2]||(E[2]=B('<h1 id="量化省下什么" tabindex="-1">量化省下什么 <a class="header-anchor" href="#量化省下什么" aria-label="Permalink to &quot;量化省下什么&quot;">​</a></h1><div class="epigraph"><p>量化省的不是算式，是字节：它把每一比特上承载的工作量加大；前提是误差预算允许你这么省。</p><footer>—— 据本仓库 KV 量化课与推理误差预算课的口径整理</footer></div><p><a href="/llm/ce-cascade-cost">上一课</a>把流量在模型谱系上分层。量化不动流量、不动模型结构，把同一个模型的字节变少。第一课拆过四笔账：权重摊销、容量积分、带宽搬运、固定开销。「量化省钱」这句口号，只有落到这四笔账上、说清省哪笔不省哪笔，才能变成工程决策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「上 INT8 能省一半钱」是把账目说丢了的说法。权重、KV、激活的量化各动不同的账：有的按比例省，有的间接省（通过批容量与打满率），有的一分不省。更常见的错法是拿理论压缩比当成本收益：权重量化到 4-bit 说「省四分之三」，可若瓶颈在 prefill 的算力、成本账上最大项根本没动。缺口是把每种量化对象映射到成本组成上，逐笔标注省与不省，再用误差预算检验允许不允许。</p><p><span class="marginnote">术语翻译：「量化」就是用更少的比特存同一个数——权重原本每个数用 16 位（FP16）存，改成 8 位（INT8）或 4 位（INT4），体积和搬运量按比例缩小，代价是数值上多了一点误差。粗略地说，像把无损音乐压成高质量 MP3：占的空间小了，音质损失要靠预算把关。</span></p><h3 id="账目映射" tabindex="-1">账目映射 <a class="header-anchor" href="#账目映射" aria-label="Permalink to &quot;账目映射&quot;">​</a></h3><p>逐项对账：权重量化（FP16 到 INT8/INT4）动两笔——显存里权重字节减半或减四分之三，decode 每步的权重搬运同步变少（带宽账），同卡装得下更多请求与 KV，批容量上移、打满率抬升（容量账的间接收益）。KV 量化动容量账与带宽账：序列容量近似翻倍、注意力扫描的字节减半，机制见 <a href="/llm/kv-quant-int8-int4">KV 量化课</a>，端侧的对应处理见 <a href="/llm/on-device-kv">端侧 KV 课</a>。激活与低精度 GEMM（FP8 等）动的是算力兑现：张量核在低精度下标称 FLOPS 更高，prefill 时长按比例缩短——这是四笔账里唯一真正加速计算的一档。不动的是：FLOPs 总量与固定开销——重试、调度、采样一次都不少。</p><p><span class="marginnote">数字实例：一个 70B 参数的模型，FP16 存权重要 \\(70 \\times 2 = 140\\) GB；INT8 减半到 70 GB，INT4 再减半到 35 GB——一张 80 GB 的卡装不下 FP16 版，却装得下 INT8 版还留出 KV 空间。这正是「批容量间接抬升」的物理来源。</span></p>',9)),(e(),l(r,null,{default:a(()=>[i(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%87%8F%E5%8C%96%22%5D%20--%3E%20WQ%5B%22%E6%9D%83%E9%87%8D%EF%BC%9AINT8%2FINT4%22%5D%0A%20%20Q%20--%3E%20KVQ%5B%22KV%EF%BC%9AINT8%2FINT4%22%5D%0A%20%20Q%20--%3E%20AQ%5B%22%E6%BF%80%E6%B4%BB%E4%B8%8E%20GEMM%EF%BC%9AFP8%22%5D%0A%20%20WQ%20--%3E%20BW%5B%22%E5%B8%A6%E5%AE%BD%E8%B4%A6%EF%BC%9A%E6%90%AC%E8%BF%90%E6%8C%89%E6%AF%94%E4%BE%8B%E9%99%8D%22%5D%0A%20%20WQ%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E8%B4%A6%EF%BC%9A%E6%89%B9%E7%A9%BA%E9%97%B4%E9%97%B4%E6%8E%A5%E6%8A%AC%22%5D%0A%20%20KVQ%20--%3E%20CAP%0A%20%20KVQ%20--%3E%20BW%0A%20%20AQ%20--%3E%20COMP%5B%22%E7%AE%97%E5%8A%9B%E8%B4%A6%EF%BC%9Aprefill%20%E6%8F%90%E9%80%9F%22%5D%0A%20%20BW%20--%3E%20MONEY%5B%22%E5%8D%95%E4%BB%B7%E4%B8%8B%E9%99%8D%22%5D%0A%20%20CAP%20--%3E%20MONEY%0A%20%20COMP%20--%3E%20MONEY%0A%20%20MONEY%20--%3E%20GATE%5B%22%E8%AF%AF%E5%B7%AE%E9%A2%84%E7%AE%97%E9%97%A8%E7%A6%81%EF%BC%9A%E9%87%8D%E6%B5%8B%E5%90%8E%E6%94%BE%E9%87%8F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按账目排序再动手：先用画像定位瓶颈账——decode 带宽主导的输出重流量，权重量化的直接收益最大；长上下文容量主导的流量，KV 量化优先；prefill 算力主导的输入重流量，只有低精度 GEMM 真正提速。然后配误差预算：<a href="/llm/num-inference-error-budget">推理误差预算课</a>给了「哪一层、哪一笔账允许掉多少」的框架，量化档位在预算内选最低比特；敏感层回退（少数层保 FP16）让平均比特数与实际收益脱钩，账要按实测算。最后重跑基准：量化后的单价必须用上一课的四钉协议重测——批容量变了，工作点也变了。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>钱从哪来：单位字节能承载的工作量变大，四笔账里的字节项按比例收缩，容量项再通过打满率间接收缩。为什么间接收益常被高估：批容量上移只在流量打得满的前提下兑现——流量不足时省出的容量只是空着，打满率不动，单价不动。为什么前提是误差预算：量化省的是钱、花的是质量，质量损失折价入账后可能倒挂——<a href="/llm/kv-cost-model">KV 成本模型课</a>的边界早已写明：不做质量折价的成本模型，会优化出便宜但不可用的系统。低比特的隐性开销也在这条机制里：权重量化后 decode 每步要做反量化，kernel 效率损失可能吃掉一部分理论带宽收益，账目按实测核销。</p>',4)),(e(),l(r,null,{default:a(()=>[i(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TH%5B%22%E7%90%86%E8%AE%BA%E6%94%B6%E7%9B%8A%EF%BC%9A%E6%8C%89%E5%8E%8B%E7%BC%A9%E6%AF%94%22%5D%20--%3E%20Q1%7B%22%E8%AF%AF%E5%B7%AE%E9%A2%84%E7%AE%97%E5%85%81%E8%AE%B8%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%E4%B8%8D%E5%85%81%E8%AE%B8%7C%20FOLD%5B%22%E8%B4%A8%E9%87%8F%E6%8A%98%E4%BB%B7%E5%85%A5%E8%B4%A6%EF%BC%8C%E5%8F%AF%E8%83%BD%E5%80%92%E6%8C%82%22%5D%0A%20%20Q1%20--%3E%7C%E5%85%81%E8%AE%B8%7C%20Q2%7B%22%E6%B5%81%E9%87%8F%E6%89%93%E5%BE%97%E6%BB%A1%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%E6%89%93%E4%B8%8D%E6%BB%A1%7C%20EMPTY%5B%22%E7%9C%81%E5%87%BA%E7%9A%84%E5%AE%B9%E9%87%8F%E7%A9%BA%E7%9D%80%EF%BC%8C%E5%8D%95%E4%BB%B7%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20Q2%20--%3E%7C%E6%89%93%E6%BB%A1%7C%20OH%5B%22%E5%AE%9E%E6%B5%8B%E6%A0%B8%E9%94%80%EF%BC%9A%E5%8F%8D%E9%87%8F%E5%8C%96%E5%BC%80%E9%94%80%E5%90%83%E6%8E%89%E4%B8%80%E5%9D%97%22%5D%0A%20%20OH%20--%3E%20CASH%5B%22%E8%B4%A6%E4%B8%8A%E7%9C%9F%E5%AE%9E%E6%94%B6%E7%9B%8A%22%5D%0A%20%20FOLD%20--%3E%20DEC%5B%22%E9%99%8D%E6%A1%A3%E4%BD%8D%E6%88%96%E6%95%8F%E6%84%9F%E5%B1%82%E5%9B%9E%E9%80%80%20FP16%22%5D%0A%20%20EMPTY%20--%3E%20DEC%0A%20%20DEC%20--%3E%20TH%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">核销的例子：权重 4-bit 理论上带宽降到四分之一，实测 decode 吞吐常只有两倍上下——反量化开销、对齐粒度与 kernel 利用率把理论值吃掉一半；预算表上写实测数，不写压缩比。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>量化不省的账要写明：固定开销、重试、prefill 的 FLOPs 总量（除低精度 GEMM 外）分文不减；输出重且批已打满的流量，量化收益以实测吞吐为准而非压缩比。敏感度分布随模型而变，上一代的逐层经验不能平移——量化档位属于模型版本的一部分，换版重配。最后，量化与级联是竞争关系不是叠加关系：把大模型量化后，它与小模型的价差缩小，级联的省钱空间同步缩水——上量化之前先看级联的账还剩多少。</p><p><span class="marginnote">常见误区：初学者容易把「压缩到 4-bit = 省四分之三的钱」直接写进预算。压缩比是存储的账，不是成本的账——若你的流量瓶颈在 prefill 算力，或批早已打满不靠量化扩容，权重量化的账上收益接近零。先定位瓶颈账，再谈压缩比。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>量化的账目映射：权重省带宽与批容量、KV 省容量与扫描、FP8 GEMM 省算力；FLOPs 总量与固定开销不省。</li><li>真正兑现要过两道门：误差预算允许、流量打得满——缺一道则理论收益不落账。</li><li>单价收益按实测核销，压缩比不是账；敏感层回退让平均比特数失真。</li><li>量化与级联互相挤压空间，动手前先比较两本账。</li><li>出处：账目框架沿用本仓库 KV 量化课、推理误差预算课、KV 成本模型课，不另造文献。</li></ul>',6))])}const T=n(d,[["render",p]]);export{_ as __pageData,T as default};
